-- ---------------------------------------------------------------------
-- Bills for every completed visit
--
-- Amounts are computed here exactly as BillingService computes them:
-- treatment cost plus the LKR 1,500 consultation fee, then the senior
-- concession, then 8% VAT on the discounted subtotal. Taxing before
-- discounting would give a different — and wrong — total.
--
-- Age is taken as at the appointment date, not today, because that is when
-- the patient was charged.
-- ---------------------------------------------------------------------
INSERT INTO bills
    (bill_id, appointment_no, consultation_fee, treatment_cost,
     discount_amount, tax_amount, total_amount,
     payment_status, payment_method, issued_by, issued_date)
SELECT
    CONCAT('BILL-', DATE_FORMAT(a.appointment_date, '%Y%m%d'), '-',
           LPAD(ROW_NUMBER() OVER (PARTITION BY a.appointment_date
                                   ORDER BY a.appointment_time), 4, '0')),
    a.appointment_no,
    1500.00                                   AS consultation_fee,
    t.base_cost                               AS treatment_cost,

    -- Senior concession, judged on the patient's age at the appointment
    -- date rather than today, because that is when they were charged.
    CASE WHEN TIMESTAMPDIFF(YEAR, p.date_of_birth, a.appointment_date) >= 65
         THEN ROUND((t.base_cost + 1500.00) * 0.10, 2)
         ELSE 0.00 END                        AS discount_amount,

    -- VAT on the discounted subtotal. Taxing first would collect VAT on
    -- money the patient never paid.
    ROUND((t.base_cost + 1500.00
           - CASE WHEN TIMESTAMPDIFF(YEAR, p.date_of_birth, a.appointment_date) >= 65
                  THEN ROUND((t.base_cost + 1500.00) * 0.10, 2)
                  ELSE 0.00 END) * 0.08, 2)   AS tax_amount,

    ROUND((t.base_cost + 1500.00
           - CASE WHEN TIMESTAMPDIFF(YEAR, p.date_of_birth, a.appointment_date) >= 65
                  THEN ROUND((t.base_cost + 1500.00) * 0.10, 2)
                  ELSE 0.00 END) * 1.08, 2)   AS total_amount,

    'PAID',
    ELT(1 + (a.patient_id % 2), 'CASH', 'CARD'),
    2,
    TIMESTAMP(a.appointment_date, a.appointment_time)
FROM appointments a
JOIN treatments t ON t.treatment_id = a.treatment_id
JOIN patients   p ON p.patient_id   = a.patient_id
WHERE a.status = 'COMPLETED'
  AND NOT EXISTS (SELECT 1 FROM bills b WHERE b.appointment_no = a.appointment_no);

SET SQL_SAFE_UPDATES = 1;

-- ---------------------------------------------------------------------
-- Verify
-- ---------------------------------------------------------------------
SELECT COUNT(*) AS patients FROM patients;
SELECT status, COUNT(*) AS n FROM appointments GROUP BY status;
SELECT COUNT(*) AS bills, ROUND(SUM(total_amount), 2) AS revenue FROM bills;
